import {configureAnalytics,track,mountConsent,safePageLocation} from './analytics.mjs';
import {SCENARIO_IDS,createScenario,transitionScenario,evaluateScenario} from './scenarios.mjs';
import {LABS,homePath,labHome,resolveRoute,translatedRoute} from './routes.mjs';
import {prepareLocalBrief} from './local-brief.mjs';
import {inspectPacket,reviseOrder,reserveUnits,inspectEquipment,reconcileReceipt,qualifyOpportunity} from './models.mjs';

const catalogue=await fetch('/cases.json').then(r=>{if(!r.ok)throw Error('Case catalogue unavailable');return r.json();}).catch(()=>null);
if(!catalogue?.cases?.length||!catalogue.cases.every(c=>SCENARIO_IDS.includes(c.id))){const host=document.getElementById('app');host.innerHTML='<main id="content" class="loading-shell"><h1>No pudimos cargar los desarrollos.<br>We could not load the developments.</h1><p>Recarga para volver a consultar el catálogo local.<br>Reload to fetch the local catalogue again.</p><button class="button" id="reload-catalogue" type="button">Recargar / Reload</button></main>';document.getElementById('reload-catalogue').addEventListener('click',()=>location.reload());throw Error('Public local catalogue unavailable');}
const CASES=catalogue.cases;
const app=document.getElementById('app');
let route=resolveRoute(location.pathname,location.search,CASES),language=route.language,filter='all',briefCase=CASES[0].id,preparedBrief=null;
const states=new Map(SCENARIO_IDS.map(id=>[id,createScenario(id)]));
const labStates=new Map(),labResults=new Map();
const briefInputs={entry:'',decision:'',output:'',tools:'',volume:'',minutes:''};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(es,en)=>language==='en'?en:es;
const text=o=>o?.[language]||'';
const money=n=>n===null||!Number.isFinite(n)?t('Por confirmar','Unconfirmed'):new Intl.NumberFormat(language==='en'?'en-US':'es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(n);
const yes=value=>value?t('Sí','Yes'):t('No','No');
const a=(href,label,cls='',scroll='')=>`<a ${scroll?`data-scroll="${esc(scroll)}"`:'data-nav'} href="${esc(href)}" class="${cls}">${label}</a>`;
const contactPath=()=>language==='en'?'https://automatizacionestorres.com/en/contact':'https://automatizacionestorres.com/conversemos';
const mainHome=()=>language==='en'?'https://automatizacionestorres.com/en':'https://automatizacionestorres.com/';
configureAnalytics({surface:'demo'});
const privacy=mountConsent({locale:language});
if(route.replace)history.replaceState({},'',route.path);

// Fixed public-route analytics only. A redraw of a model is not a page navigation.
let analyticsNavigation=0,lastAnalyticsRoute=null;
const analyticsResultCategory=value=>['ready','needs_review','invalid','blocked','unchanged'].includes(value)?value:'needs_review';
function measureAnalyticsSections(){
 const height=window.innerHeight;if(!height)return;
 for(const [selector,section_id] of [['.hero','home'],['#desarrollos','developments'],['.principles','principles'],['.case-head','case'],['#probar','simulation'],['#resultado-del-desarrollo','result'],['#laboratorio','lab'],['#brief-builder','brief'],['#contacto','collaborate']]){
  const box=document.querySelector(selector)?.getBoundingClientRect();
  if(box&&box.top<height*.8&&box.bottom>Math.min(120,height*.3))track('section_view',{section_id,ui_language:language},{dedupeKey:'demo-section:'+analyticsNavigation+':'+section_id});
 }
}
function trackRouteNavigation(initial=false){
 const current=safePageLocation(location,'demo')+'|'+language;if(current===lastAnalyticsRoute)return;
 lastAnalyticsRoute=current;analyticsNavigation++;
 if(!initial)track('page_view',{ui_language:language},{dedupeKey:'demo-navigation:'+analyticsNavigation});
 if(route.view==='case')track('demo_case_select',{example_id:route.caseId,ui_language:language});
 if(route.view==='lab')track('demo_case_select',{example_id:route.legacyId,ui_language:language});
 requestAnimationFrame(measureAnalyticsSections);
}

