function header(){return`<header class="site-header"><div class="container header-inner">${a(homePath(language),'<img src="/assets/v38/at-mark.svg" width="46" height="46" alt=""><span class="brand-word"><small>Automatizaciones</small><strong>Torres</strong></span>','brand')}<nav class="header-nav" id="site-nav" aria-label="${t('Principal','Main')}">${a(homePath(language),t('Desarrollos','Developments'),'','desarrollos')}${a(labHome(language),t('Laboratorio','Control lab'))}<a href="${contactPath()}">${t('Hablemos de tu proceso','Discuss your workflow')}</a></nav><div class="header-controls"><a class="header-main-link" href="${mainHome()}">${t('Sitio principal','Main website')}</a><button class="language-button" id="language-switch" type="button" aria-label="${t('Switch to English','Cambiar a español')}">${language==='es'?'EN':'ES'}</button><button class="menu-button" id="menu-toggle" type="button" aria-expanded="false" aria-controls="site-nav">${t('Menú','Menu')}</button></div></div></header>`;}
function footer(){return`<footer class="container site-footer"><span>© 2026 Automatizaciones Torres</span><span>${t('Muestras independientes. Datos ficticios.','Independent samples. Fictional data.')}</span><a href="https://github.com/satorresa/automatizaciones-torres-demo" target="_blank" rel="noopener noreferrer">${t('Repositorio de demostraciones','Demonstration repository')}</a></footer>`;}
function contact(){return`<section class="contact-section" id="contacto"><div class="container contact-inner"><div><p class="eyebrow">${t('DE LA MUESTRA A TU OPERACIÓN','FROM THE SAMPLE TO YOUR OPERATION')}</p><h2>${t('¿Dónde necesita<br><em>avanzar tu equipo?</em>','Where does your team<br><em>need to move forward?</em>')}</h2><p>${t('Podemos empezar por un pedido, un soporte o una decisión concreta. Revisamos el recorrido, las herramientas que ya funcionan y qué tendría que conservar una primera entrega.','We can start with an order, a supporting record or a specific decision. We review the workflow, the tools that already work and what a first delivery needs to retain.')}</p></div><div class="contact-actions"><a class="button" href="${contactPath()}">${t('Compartir mi caso','Share my case')}</a><a class="text-link" data-contact="email" href="mailto:automatizaciones.storres@gmail.com">automatizaciones.storres@gmail.com</a><a class="text-link" data-contact="whatsapp" href="https://wa.me/573105497003" target="_blank" rel="noopener noreferrer">WhatsApp · 310 549 7003</a></div></div></section>`;}
const previewRow=(label,value)=>`<div class="preview-row"><span>${label}</span><strong>${esc(value)}</strong></div>`;
const previewCell=(label,value)=>`<div class="preview-cell"><span>${label}</span><strong>${esc(value)}</strong></div>`;
function preview(c){const s=createScenario(c.id),r=evaluateScenario(s);let body='';
 if(c.id==='evidence-workspace')body=`<p class="preview-title">${t('Entrega del periodo','Period submission')}</p><div class="preview-grid">${previewCell(t('Periodo solicitado','Requested period'),s.expectedPeriod)}${previewCell(t('Documento recibido','Received document'),s.documentPeriod)}</div><span class="preview-status">${t('Periodo distinto · revisión pendiente','Different period · review pending')}</span>`;
 if(c.id==='document-consistency')body=`<p class="preview-title">${t('Referencia y soporte','Reference and evidence')}</p>${previewRow(t('Registro de referencia','Reference record'),t('Registro A','Record A'))}${previewRow(t('Identidad en el soporte','Identity on the document'),t('Registro B','Record B'))}<span class="preview-status">${t('Pedir aclaración con una referencia visible','Request clarification with a visible reference')}</span>`;
 if(c.id==='order-operations')body=`<p class="preview-title">${t('Pedido por registrar','Order to record')}</p>${previewRow(t('Artículo de muestra','Sample item'),t('Kit de montaje','Assembly kit'))}${previewRow(t('Unidades / saldo disponible','Units / available'),s.units+' / '+r.facts.available)}<div class="preview-steps"><div class="preview-step"><strong>01</strong>${t('Validar','Validate')}</div><div class="preview-step"><strong>02</strong>${t('Intento','Attempt')}</div><div class="preview-step"><strong>03</strong>${t('Recibo','Receipt')}</div></div>`;
 if(c.id==='customer-order-portal')body=`<p class="preview-title">${s.reference}</p><div class="preview-grid">${previewCell(t('Versión del cliente','Customer revision'),'04')}${previewCell(t('Versión actual','Current revision'),'05')}</div><span class="preview-status">${t('Un cambio necesita la versión vigente','A change needs the current revision')}</span>`;
 if(c.id==='commerce-operations')body=`<p class="preview-title">${t('Resumen de pedido','Order summary')}</p>${previewRow(t('Producto ficticio','Fictional product'),t('Bolso de muestra','Sample bag'))}${previewRow(t('Total del ejemplo','Sample total'),money(s.expectedAmount))}${previewRow(t('Pago / despacho','Payment / fulfillment'),t('Sin confirmar / pendiente','Unconfirmed / pending'))}`;
 if(c.id==='transport-settlement')body=`<p class="preview-title">${t('Dos revisiones, una liquidación','Two reviews, one settlement')}</p><div class="preview-grid">${previewCell(t('Ajuste · revisión A','Adjustment · review A'),money(s.adjustmentA))}${previewCell(t('Ajuste · revisión B','Adjustment · review B'),money(s.adjustmentB))}</div><span class="preview-status">${t('Diferencia por resolver:','Difference to resolve:')} ${money(Math.abs(s.adjustmentA-s.adjustmentB))}</span>`;
 if(c.id==='operations-product-design')body=`<p class="preview-title">${t('Separar antes de sumar','Separate before adding')}</p>${previewRow(t('Anticipo del ejemplo','Sample advance'),money(s.advance))}${previewRow(t('Costo con soporte','Supported cost'),money(s.supportedCost))}${previewRow(t('Pendiente por legalizar','Unsettled advance'),money(r.facts.unsettledAdvance))}<span class="preview-status">${t('Modelo conceptual · no producto desplegado','Conceptual model · not a deployed product')}</span>`;
 if(c.id==='commercial-operations')body=`<div class="preview-letter">${r.facts.tier}</div><p class="preview-title">${t('Solicitud explícita ficticia','Fictional explicit request')}</p>${previewRow(t('Fuente y vía revisadas','Source and route reviewed'),yes(true))}${previewRow(t('Siguiente paso aprobado','Next step approved'),yes(false))}<span class="preview-status">${t('La señal no autoriza el contacto','A signal does not authorize contact')}</span>`;
 if(c.id==='private-case-intake')body=`<p class="preview-title">${t('Revisar antes de enviar','Review before submitting')}</p>${previewRow(t('Archivo ficticio','Fictional file'),s.file)}${previewRow(t('Versión preparada','Prepared version'),'01')}<div class="preview-steps"><div class="preview-step"><strong>01</strong>${t('Contexto','Context')}</div><div class="preview-step"><strong>02</strong>${t('Revisión','Review')}</div><div class="preview-step"><strong>03</strong>${t('Recibo','Receipt')}</div></div>`;
 return`<div class="preview"><div class="preview-head"><span>${t('INTERFAZ DE DEMOSTRACIÓN','DEMONSTRATION INTERFACE')}</span><span>AT</span></div><div class="preview-body">${body}</div></div>`;
}
function card(c,index){return`<article class="development-card ${index===0&&filter==='all'?'featured':''}"><a class="card-visual" data-nav href="${c.routes[language]}" aria-label="${esc(t("Explorar ","Explore ")+text(c.title))}"><img class="case-capture" src="/assets/v38/cases/${c.id}-${language}.webp" alt="${t("Captura de la demostración funcionando con datos ficticios","Screenshot of the working demonstration with fictional data")}" width="1280" height="720" loading="lazy"></a><div class="card-body"><div class="card-topline"><span class="case-number">${String(CASES.indexOf(c)+1).padStart(2,'0')}</span><span class="case-kind">${esc(text(c.status))}</span></div><p class="card-category">${esc(text(c.category))}</p><h3>${esc(text(c.title))}</h3><p>${esc(text(c.challenge))}</p><a data-nav class="card-link" aria-label="${esc(t('Abrir desarrollo: ','Open development: ')+text(c.title))}" href="${c.routes[language]}">${t('Abrir el desarrollo','Open the development')}</a></div></article>`;}
function selectedCases(){return CASES.filter(c=>filter==='all'||filter==='prototype'&&c.status.type==='functional_prototype'||filter==='design'&&c.status.type==='product_discovery'||filter==='functional'&&!['functional_prototype','product_discovery'].includes(c.status.type));}
function filters(){return[['all',t('Todos','All')],['functional',t('Aplicaciones y módulos','Applications and modules')],['prototype',t('Prototipo','Prototype')],['design',t('Diseño de producto','Product design')]].map(([id,label])=>`<button type="button" class="filter-button" data-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('');}
function home(){return`<main id="content"><section class="hero"><img class="hero-photo" src="/assets/v38/hero-operations.webp" alt="" width="1672" height="941" fetchpriority="high"><div class="hero-screen"></div><div class="container"><div class="hero-content"><p class="eyebrow">${t('DESARROLLOS · SISTEMAS · DECISIONES','DEVELOPMENTS · SYSTEMS · DECISIONS')}</p><h1>${t('Desarrollos<br><em>destacados</em>','Featured<br><em>developments</em>')}</h1><p class="intro">${t('Explora sistemas de expedientes, pedidos, comercio y transporte. Cada caso muestra el recorrido, lo que construimos y las decisiones que permite tomar.','Explore systems for documents, orders, commerce and transport. Each case shows the workflow, what we built and the decisions it supports.')}</p><div class="hero-actions"><a class="button" href="${homePath(language)}" data-scroll="desarrollos">${t('Explorar desarrollos','Explore developments')}</a>${a(CASES[0].routes[language],t('Abrir un expediente','Open an evidence record'),'text-link')}</div><p class="hero-note">${t('Nueve historias de producto. Ejemplos interactivos con datos ficticios.','Nine product stories. Interactive examples with fictional data.')}</p></div></div><span class="illustration-note">${t('IMAGEN ILUSTRATIVA','ILLUSTRATIVE IMAGE')}</span></section><div class="container principles">${[[t('Entradas','Inputs'),t('Un objeto que se puede revisar.','An object that can be reviewed.')],[t('Reglas','Rules'),t('Condiciones que explican un pendiente.','Conditions that explain a pending step.')],[t('Decisión','Decision'),t('Una persona conserva el criterio.','A person retains judgment.')],[t('Rastro','Record'),t('Lo que cambió queda en su contexto.','Changes retain their context.')]].map(([title,body])=>`<div class="principle"><strong>${title}</strong><p>${body}</p></div>`).join('')}</div><section class="container section" id="desarrollos"><div class="section-head"><div><p class="eyebrow">${t('DESARROLLOS DESTACADOS','FEATURED DEVELOPMENTS')}</p><h2>${t('El trabajo detrás<br><em>de cada sistema.</em>','The work behind<br><em>each system.</em>')}</h2></div><p>${t('Aplicaciones, módulos y prototipos con un recorrido concreto. En cada historia puedes ver qué quedó construido, probar una excepción y entender qué decisión sigue en manos del equipo.','Applications, modules and prototypes with a concrete workflow. Each story shows what was built, lets you try an exception and explains which decision stays with the team.')}</p></div><div class="filters" aria-label="${t('Filtrar desarrollos','Filter developments')}">${filters()}</div><div class="development-grid" id="development-grid">${selectedCases().map(card).join('')}</div><p class="selection-note">${t('Cada ficha identifica el tipo de entregable y su alcance. Las muestras usan datos de demostración.','Each case identifies the type of deliverable and its scope. The samples use demonstration data.')}</p><div class="lab-invitation" id="laboratorio"><div><h3>${t('Seis controles, para ir al detalle.','Six controls, for a closer look.')}</h3><p>${t('Los modelos originales siguen disponibles: documento, cambio de pedido, reserva, servicio, abono y contexto comercial.','The original models remain available: document, order change, reservation, service, receipt and commercial context.')}</p></div>${a(labHome(language),t('Abrir el laboratorio','Open the control lab'),'button button-outline')}</div></section>${briefSection()}${contact()}</main>`;}
function field(s,key,label,kind='text',options=[]){const id='control-'+key;if(kind==='checkbox')return`<label class="control-field check" for="${id}"><input id="${id}" data-field="${key}" type="checkbox" ${s[key]?'checked':''}><span>${label}</span></label>`;if(kind==='select')return`<label class="control-field" for="${id}"><span>${label}</span><select id="${id}" data-field="${key}">${options.map(([value,title])=>`<option value="${esc(value)}" ${s[key]===value?'selected':''}>${esc(title)}</option>`).join('')}</select></label>`;if(kind==='textarea')return`<label class="control-field" for="${id}"><span>${label}</span><textarea id="${id}" data-field="${key}" maxlength="300">${esc(s[key])}</textarea></label>`;return`<label class="control-field" for="${id}"><span>${label}</span><input id="${id}" data-field="${key}" type="${kind}" value="${esc(s[key])}" ${kind==='number'?'min="0" step="any"':'maxlength="80"'}></label>`;}
const roles=(s,list)=>field(s,'role',t('Rol ficticio','Fictional role'),'select',list.map(x=>[x,t(...ROLE_NAMES[x])]));
const button=(type,label,primary=false,extra='')=>`<button type="button" class="button ${primary?'button-wine':'button-outline'}" data-action="${type}" ${extra}>${label}</button>`;
const provider=s=>field(s,'providerOutcome',t('Respuesta simulada','Simulated response'),'select',[['uncertain',t('Sin confirmación','Unconfirmed')],['confirmed',t('Confirmada','Confirmed')],['failed',t('Rechazada','Rejected')]]);
function controls(s){let fields='',actions='';switch(s.caseId){
 case'evidence-workspace':fields=roles(s,['reviewer','contributor'])+field(s,'documentPeriod',t('Periodo del documento','Document period'),'select',[['2026-04','2026-04'],['2026-05','2026-05']])+field(s,'attachment',t('Documento adjunto','Document attached'),'checkbox');actions=button('correct',t('Usar el periodo solicitado','Use the requested period'))+button('approve',t('Aceptar entrega','Accept submission'),true)+button('stale',t('Abrir revisión anterior','Open older review'))+button('refresh',t('Leer versión actual','Read current revision'))+button('close',t('Cerrar expediente','Close record'))+button('reopen',t('Reabrir expediente','Reopen record'));break;
 case'document-consistency':fields=roles(s,['reviewer','viewer'])+field(s,'documentHolder',t('Identidad del soporte','Document identity'),'select',[['Registro A',t('Registro A','Record A')],['Registro B',t('Registro B','Record B')]])+field(s,'documentPeriod',t('Periodo del soporte','Document period'),'select',[['2026-07','2026-07'],['2026-06','2026-06']])+field(s,'readable',t('Archivo legible','Readable file'),'checkbox')+field(s,'sourcePresent',t('Referencia disponible','Reference available'),'checkbox');actions=button('correct',t('Usar soporte correspondiente','Use matching evidence'))+button('review',t('Registrar revisión','Record review'),true);break;
 case'order-operations':fields=roles(s,['operator','viewer'])+field(s,'units',t('Unidades solicitadas','Requested units'),'number')+provider(s)+field(s,'permission',t('Permiso de operación vigente','Operation permission current'),'checkbox');actions=button('submit',t('Registrar intento','Record attempt'),true)+button('check',t('Consultar recibo','Inspect receipt'));break;
 case'customer-order-portal':fields=roles(s,['customer','staff']);actions=button('request',t('Solicitar cancelación','Request cancellation'),true)+button('resolve',t('Resolver solicitud','Resolve request'))+button('refresh',t('Leer versión actual','Read current revision'))+button('revoke',t('Retirar acceso de muestra','Revoke sample access'));break;
 case'commerce-operations':fields=roles(s,['buyer','admin'])+field(s,'reportedAmount',t('Importe reportado · COP','Reported amount · COP'),'number')+field(s,'proofPresent',t('Soporte de muestra presente','Sample evidence present'),'checkbox');actions=button('report',t('Reportar pago ficticio','Report fictional payment'),true)+button('confirm',t('Confirmar revisión del abono','Confirm payment review'))+button('prepare',t('Marcar preparación','Mark preparation'));break;
 case'transport-settlement':fields=roles(s,['reviewer','supervisor','finance'])+field(s,'quantity',t('Cantidad validada','Verified quantity'),'number')+field(s,'adjustmentA',t('Ajuste revisión A · COP','Review A adjustment · COP'),'number')+field(s,'adjustmentB',t('Ajuste revisión B · COP','Review B adjustment · COP'),'number')+field(s,'evidence',t('Soportes del viaje completos','Trip evidence complete'),'checkbox');actions=button('resolve',t('Resolver con revisión A','Resolve with review A'),false,'data-choice="first"')+button('resolve',t('Resolver con revisión B','Resolve with review B'),false,'data-choice="second"')+button('approve',t('Confirmar liquidación ficticia','Confirm fictional settlement'),true);break;
 case'operations-product-design':fields=roles(s,['analyst','reviewer'])+field(s,'advance',t('Anticipo ficticio · COP','Fictional advance · COP'),'number')+field(s,'supportedCost',t('Costo con soporte · COP','Supported cost · COP'),'number')+field(s,'supportPresent',t('Soporte disponible','Evidence available'),'checkbox');actions=button('review',t('Revisar el modelo','Review the model'),true);break;
 case'commercial-operations':fields=roles(s,['reviewer','viewer'])+field(s,'signal',t('Situación de muestra','Sample situation'),'select',[['explicit',t('Solicitud explícita','Explicit request')],['activity',t('Actividad operativa','Operational activity')],['fit',t('Encaje por investigar','Fit to investigate')]])+[['sourceVerified',t('Fuente verificada','Source verified')],['sourceFresh',t('Vigencia revisada','Freshness reviewed')],['routeReviewed',t('Vía de contacto revisada','Contact route reviewed')],['priorContact',t('Existe contacto previo','Prior contact exists')],['suppressed',t('No contactar','Do not contact')],['acknowledged',t('Acuse automático recibido','Automatic acknowledgment received')]].map(([key,label])=>field(s,key,label,'checkbox')).join('');actions=button('approve',t('Revisar el siguiente paso','Review the next step'),true);break;
 case'private-case-intake':fields=field(s,'summary',t('Recorrido ficticio','Fictional workflow'),'textarea')+provider(s)+field(s,'fileAllowed',t('Archivo de muestra permitido','Sample file allowed'),'checkbox');actions=button('review',t('Revisar versión','Review version'),true)+button('submit',t('Simular recepción','Simulate receipt'))+button('check',t('Recuperar estado','Recover status'));break;
 }return`<aside class="controls-panel"><div class="controls-label">${t('CAMBIA UNA CONDICIÓN','CHANGE A CONDITION')}</div>${fields}<div class="action-stack">${actions}</div><p class="control-note">${t('Roles, documentos y registros de demostración. Ninguna acción utiliza sistemas, personas o dinero reales.','Demonstration roles, documents and records. No action uses real systems, people or funds.')}</p></aside>`;}
const FACT_NAMES={expectedPeriod:['Periodo de referencia','Reference period'],documentPeriod:['Periodo del documento','Document period'],version:['Versión actual','Current version'],reviewVersion:['Versión en revisión','Revision under review'],approved:['Revisión aceptada','Review accepted'],archives:['Cierres conservados','Retained closures'],referenceHolder:['Identidad de referencia','Reference identity'],documentHolder:['Identidad del soporte','Document identity'],referencePeriod:['Periodo de referencia','Reference period'],readable:['Lectura disponible','Readable'],reviewed:['Revisión registrada','Review recorded'],decision:['Decisión documental','Document decision'],reference:['Referencia de muestra','Sample reference'],units:['Unidades','Units'],available:['Saldo disponible','Available units'],attempts:['Intentos del ejemplo','Sample attempts'],orders:['Órdenes de muestra','Sample orders'],receipt:['Recibo','Receipt'],currentRevision:['Versión actual','Current revision'],visibleRevision:['Versión visible','Visible revision'],requested:['Cambio solicitado','Change requested'],status:['Estado del pedido','Order state'],active:['Acceso vigente','Access current'],visibleOrders:['Órdenes visibles','Visible orders'],expectedAmount:['Importe de muestra','Sample amount'],reportedAmount:['Importe reportado','Reported amount'],reported:['Aviso del comprador','Buyer notification'],confirmed:['Revisión confirmada','Review confirmed'],stockRemaining:['Unidades restantes','Remaining units'],fulfillment:['Preparación del pedido','Order preparation'],quantity:['Cantidad validada','Verified quantity'],gross:['Base de la muestra','Sample base'],advance:['Anticipo ficticio','Fictional advance'],adjustmentA:['Ajuste revisión A','Review A adjustment'],adjustmentB:['Ajuste revisión B','Review B adjustment'],resolvedAdjustment:['Ajuste resuelto','Resolved adjustment'],due:['Saldo candidato · no utilidad','Candidate balance · not profit'],supportedCost:['Costo con soporte','Supported cost'],unsettledAdvance:['Anticipo por legalizar','Unsettled advance'],additionalCost:['Costo adicional','Additional cost'],productionProduct:['Producto en producción','Production product'],tier:['Clase de evidencia','Evidence class'],routeReviewed:['Vía revisada','Route reviewed'],priorContact:['Historial previo','Prior history'],suppressed:['Supresión activa','Suppression active'],humanApproved:['Paso revisado','Step reviewed'],acknowledged:['Acuse automático','Automatic acknowledgment'],sent:['Mensajes enviados','Messages sent'],meetings:['Reuniones creadas','Meetings created'],sales:['Ventas registradas','Sales recorded'],reviewedVersion:['Versión revisada','Reviewed version'],file:['Archivo ficticio','Fictional file'],receiptStatus:['Estado del recibo','Receipt state'],records:['Registros confirmados','Confirmed records'],emailsSent:['Correos enviados','Emails sent'],bookings:['Citas creadas','Bookings created']};
Object.assign(FACT_NAMES,{existingReservation:['Reserva ya registrada','Reservation already recorded'],reservedNow:['Unidades reservadas ahora','Units reserved now'],tagged:['Equipo identificado','Equipment identified'],authorized:['Trabajo autorizado','Work authorized'],attachment:['Soporte de servicio','Service evidence'],changeCount:['Cambios detectados','Detected changes'],sampleMeeting:['Reunión indicada en el ejemplo','Meeting indicated in the example'],recognizedIncome:['Ingreso real reconocido','Real income recognized'],difference:['Diferencia del abono','Receipt difference']});
const VALUES={none:['Sin registro','No record'],submitted:['Solicitud registrada','Request recorded'],on_hold:['Pendiente de resolución','Awaiting resolution'],cancelled:['Cancelado en la muestra','Cancelled in the sample'],pending:['Pendiente','Pending'],prepared:['Preparado en la muestra','Prepared in the sample'],confirmed:['Confirmado en la muestra','Confirmed in the sample'],uncertain:['Por confirmar','Unconfirmed'],failed:['Rechazado','Rejected'],received:['Recibido en la muestra','Received in the sample'],clarification:['Pedir aclaración','Request clarification'],document_consistent:['Coherencia documental','Document consistency'],review:['Por validar','To validate'],'Registro A':['Registro A','Record A'],'Registro B':['Registro B','Record B']};
const MONEY_KEYS=new Set(['expectedAmount','reportedAmount','gross','advance','adjustmentA','adjustmentB','resolvedAdjustment','due','supportedCost','unsettledAdvance','additionalCost','recognizedIncome','difference']);
function valueFor(key,value){if(value===null||value===undefined)return t('Por confirmar','Unconfirmed');if(typeof value==='boolean')return yes(value);if(MONEY_KEYS.has(key))return money(value);return VALUES[value]?t(...VALUES[value]):String(value);}
function factsGrid(facts){return`<div class="facts-grid">${Object.entries(facts).map(([key,value])=>{const v=valueFor(key,value);return`<div class="fact"><span class="fact-label">${esc(FACT_NAMES[key]?t(...FACT_NAMES[key]):key)}</span><strong class="fact-value ${v.length>24?'long':''}">${esc(v)}</strong></div>`;}).join('')}</div>`;}
function scenarioGuidance(s){switch(s.caseId){case'evidence-workspace':return s.closed?t('La fotografía del cierre se conserva. Reabre para iniciar otra revisión sin reemplazarla.','The closure snapshot is retained. Reopen to begin another review without replacing it.'):s.approvedVersion===s.version?t('La versión vigente fue aceptada. Ahora puedes cerrar el expediente.','The current version was accepted. You can now close the record.'):s.documentPeriod!==s.expectedPeriod?t('El soporte corresponde a otro periodo. Corrígelo y prueba qué pasa si intentas revisar una versión anterior.','The evidence belongs to another period. Correct it and try reviewing an older revision.'):t('Las comprobaciones están completas. El revisor debe aceptar esta versión antes del cierre.','Checks are complete. The reviewer must accept this version before closure.');case'document-consistency':return t('Compara identidad, periodo y fuente. Una revisión puede terminar en aclaración o en coherencia documental; nunca determina por sí sola cumplimiento legal o pago actual.','Compare identity, period and source. Review may result in clarification or document consistency; it never independently determines legal compliance or current payment.');case'order-operations':return s.receipt?.status==='uncertain'?t('El intento quedó sin confirmar. Cambia la respuesta simulada a Confirmada y consulta el recibo antes de repetir.','The attempt is unconfirmed. Change the simulated response to Confirmed and inspect the receipt before retrying.'):s.receipt?.status==='confirmed'?t('Existe una sola orden para esta referencia. Repetir el mismo registro no crea otra ni otro intento.','There is one order for this reference. Repeating the same submission creates neither another order nor another attempt.'):t('El primer intento usa un proveedor simulado. La falta de respuesta no se convierte en confirmación.','The first attempt uses a simulated provider. A missing response is not converted into confirmation.');case'customer-order-portal':return !s.active&&s.role==='customer'?t('El acceso del cliente fue retirado. El registro sigue existiendo para la operación autorizada.','Customer access was revoked. The record still exists for authorized staff.'):t('El cliente pide el cambio. Para resolverlo, cambia a Operación y lee la versión actual; la revisión anterior no es suficiente.','The customer requests the change. To resolve it, switch to Staff and read the current revision; the older review is insufficient.');case'commerce-operations':return t('Reportar un soporte no confirma el abono. Cambia a Administración para revisar el importe y confirmar; la preparación del pedido sigue siendo otro paso.','Reporting evidence does not confirm funds. Switch to Administration to review the amount and confirm; order preparation remains a separate step.');case'transport-settlement':return t('Las revisiones A y B proponen ajustes distintos. Supervisión resuelve la diferencia; Revisión financiera confirma después. El saldo es una liquidación candidata ficticia, no utilidad ni un pago ejecutado.','Reviews A and B propose different adjustments. The Supervisor resolves the difference; the Finance reviewer confirms afterward. The balance is a fictional candidate settlement, not profit or an executed payment.');case'operations-product-design':return t('La muestra separa el anticipo del costo soportado. La revisión comprueba el modelo conceptual; no convierte la tesis en un producto implantado.','The sample separates an advance from supported cost. Review checks the conceptual model; it does not turn the thesis into an implemented product.');case'commercial-operations':return t('Una fuente, la vía y el historial se revisan por separado. Activa No contactar para ver cómo la supresión conserva el bloqueo. Un acuse no crea reuniones ni ventas.','Source, route and history are reviewed separately. Turn on Do not contact to see how suppression keeps the block. Acknowledgment creates no meetings or sales.');case'private-case-intake':return s.receipt?.status==='uncertain'?t('El intento no tiene confirmación. Selecciona una respuesta simulada confirmada y recupera el estado; no repitas el alta.','The attempt is unconfirmed. Select a confirmed simulated response and recover its status; do not repeat creation.'):t('Revisa el contexto antes de simular la recepción. Modificarlo invalida la revisión. La muestra no usa el formulario real, correo ni agenda.','Review context before simulating receipt. Editing invalidates review. The sample uses no live form, email or calendar.');}}
const SIMULATION_HEADINGS={"evidence-workspace": ["Revisar sin perder la versión.", "Review without losing the revision."], "document-consistency": ["Un soporte frente a su referencia.", "Evidence against its reference."], "order-operations": ["Recuperar el intento, conservar el pedido.", "Recover the attempt. Retain the order."], "customer-order-portal": ["Pedir un cambio. Resolverlo con control.", "Request a change. Resolve it with control."], "commerce-operations": ["Del aviso de pago a la revisión.", "From payment notice to review."], "transport-settlement": ["Resolver diferencias antes de liquidar.", "Resolve differences before settlement."], "operations-product-design": ["Comprobar el modelo antes de construir.", "Check the model before building."], "commercial-operations": ["Priorizar sin saltarse el historial.", "Prioritize without skipping history."], "private-case-intake": ["Revisar, recibir y recuperar el mismo caso.", "Review, receive and recover the same case."]};
function renderSessionHistory(s){return`<div class="history-box"><h4>${t('Rastro de esta sesión de muestra','This sample session history')}</h4>${s.history.length?s.history.slice(-6).map(x=>`<div class="history-row"><span>${String(x.sequence).padStart(2,'0')}</span><div><strong>${esc(x.result==='recorded'?(ACTION_NAMES[x.action]?t(...ACTION_NAMES[x.action]):t('Acción de muestra','Sample action')):t('Acción no realizada','Action not performed'))}</strong><br>${esc(x.result==='recorded'?t(...ROLE_NAMES[x.role]):issue(x.result))}</div></div>`).join(''):`<p class="history-empty">${t('Cambia una condición o prueba una acción. Las decisiones aparecerán aquí; no son eventos de un sistema real.','Change a condition or try an action. Decisions appear here; they are not events from a real system.')}</p>`}</div>`;}
function simulation(c){const s=states.get(c.id),r=evaluateScenario(s);return`<div class="workspace" data-capture="${c.id}">${controls(s)}<div class="result-panel" id="result-panel" role="region" aria-label="${t('Estado de la muestra','Sample state')}">${s.lastIssue?`<div class="action-alert" role="status">${esc(issue(s.lastIssue))}</div>`:''}<div class="result-top"><div><span class="system-label">${t('ESTADO DEL EJEMPLO','EXAMPLE STATE')}</span><h3>${esc(stage(r.stage))}</h3></div><span class="state-label ${r.category==='ready'?'ready':''}">${t('DATOS FICTICIOS','FICTIONAL DATA')}</span></div>${factsGrid(r.facts)}${r.issues.length?`<ul class="check-list">${r.issues.map((x,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><span>${esc(issue(x))}</span></li>`).join('')}</ul>`:''}<p class="result-explanation" aria-live="polite">${scenarioGuidance(s)}</p>${renderSessionHistory(s)}${s.archives?.length?`<div class="history-box"><h4>${t("CIERRES QUE SE CONSERVAN","RETAINED CLOSURES")}</h4>${s.archives.map(x=>`<div class="history-row"><span>${String(x.closure).padStart(2,"0")}</span><div><strong>${t("Versión","Version")} ${x.version}</strong><br>${t("Periodo","Period")} ${esc(x.period)}</div></div>`).join("")}</div>`:""}</div></div>`;}
function casePage(c){const index=CASES.indexOf(c),next=CASES[(index+1)%CASES.length];return`<main id="content"><div class="container"><section class="case-head"><div class="breadcrumb">${a(homePath(language),t('Desarrollos','Developments'),'','desarrollos')}<span>/</span><span>${esc(text(c.category))}</span></div><p class="eyebrow">${t('DESARROLLO','DEVELOPMENT')} ${String(index+1).padStart(2,'0')}</p><h1>${esc(text(c.title))}</h1><p class="lead">${esc(text(c.challenge))}</p><div class="case-head-meta"><span class="status-chip">${esc(text(c.status))}</span><span class="fiction-note">${t('Interfaz reconstruida · datos ficticios','Reconstructed interface · fictional data')}</span></div><div class="hero-actions case-head-actions"><a class="button" href="${c.routes[language]}" data-scroll="simulation-root">${t('Probar el recorrido','Try the workflow')}</a><a class="text-link" href="${c.routes[language]}" data-scroll="resultado-del-desarrollo">${t('Qué se comprobó','What was verified')}</a></div></section><section class="story-intro"><h2>${t('Qué quedó<br><em>construido.</em>','What<br><em>was built.</em>')}</h2><p>${esc(text(c.built))}</p></section><section class="workflow-section"><p class="eyebrow">${t('EL RECORRIDO','THE WORKFLOW')}</p><h2>${t('Cada paso conserva contexto.','Each step retains context.')}</h2><div class="workflow-rows">${c.workflow.map((x,i)=>`<div class="workflow-row"><span>${String(i+1).padStart(2,'0')}</span><p>${esc(text(x))}</p></div>`).join('')}</div></section></div><section class="simulation-section" id="probar"><div class="container"><div class="simulation-heading"><div><p class="eyebrow">${t('PRUEBA EL RECORRIDO','TRY THE WORKFLOW')}</p><h2>${esc(t(...SIMULATION_HEADINGS[c.id]))}</h2><p>${esc(text(c.demo))}</p></div><button class="text-link" data-reset type="button">${t('Restablecer ejemplo','Reset example')}</button></div><div id="simulation-root">${simulation(c)}</div><div class="exception-note"><div><h3>${t('CUANDO ALGO CAMBIA','WHEN SOMETHING CHANGES')}</h3><p>${esc(text(c.exception))}</p></div><div><h3>${t('LA DECISIÓN HUMANA','THE HUMAN DECISION')}</h3><p>${esc(text(c.humanDecision))}</p></div></div></div></section><div class="container"><section class="case-record" id="resultado-del-desarrollo"><div><p class="eyebrow">${t('RESULTADO EVIDENCIADO','EVIDENCED RESULT')}</p><h2>${t('Lo que permite<br>comprobar este trabajo.','What this work<br>lets us verify.')}</h2><p>${esc(text(c.evidencedResult))}</p><details><summary>${t('Alcance y límites del desarrollo','Development scope and boundaries')}</summary><p>${esc(text(c.scope))}</p></details></div><div class="measurement"><p class="eyebrow">${t('UNA MEDIDA POR VALIDAR','A MEASURE TO VALIDATE')}</p><h2>${t('Medir sobre<br>un caso concreto.','Measure against<br>a concrete case.')}</h2><p>${esc(text(c.measure))}</p><button class="button button-outline" data-snapshot type="button">${t('Descargar esta muestra ficticia','Download this fictional sample')}</button></div></section><div class="next-cases"><div class="next-case-links"><a href="${homePath(language)}" data-brief-case="${c.id}">${t('Llevar mi proceso a una ficha','Describe my workflow in a brief')}</a>${a(next.routes[language],t('Siguiente: ','Next: ')+esc(text(next.title)))}</div></div></div>${contact()}</main>`;}
function briefSection(){const c=CASES.find(x=>x.id===briefCase)||CASES[0];return`<section class="container brief-section" id="brief-builder"><div class="brief-heading"><p class="eyebrow">${t('TU PRIMER RECORRIDO','YOUR FIRST WORKFLOW')}</p><h2>${t('Pasar de una idea<br><em>a una conversación.</em>','Move from an idea<br><em>to a conversation.</em>')}</h2><p>${t('Describe qué llega, quién debe decidir y qué necesitas obtener. La ficha se prepara en este navegador para que puedas revisarla, copiarla o descargarla.','Describe what comes in, who needs to decide and what you need to obtain. The brief is prepared in this browser for you to review, copy or download.')}</p><p class="quiet">${t('Ejemplo de referencia: ','Reference example: ')}${esc(text(c.title))}</p></div><div class="brief-layout"><form class="brief-form" id="brief-form" novalidate>${[['entry',t('Qué llega al proceso','What comes into the workflow')],['decision',t('Quién decide y qué debe confirmar','Who decides and what they confirm')],['output',t('Qué debería salir','What should come out')]].map(([key,label])=>`<label class="control-field wide" for="brief-${key}"><span>${label}</span><textarea id="brief-${key}" name="${key}" data-brief-input="${key}" maxlength="${key==='decision'?300:400}" required>${esc(briefInputs[key])}</textarea></label>`).join('')}<label class="control-field wide" for="brief-tools"><span>${t('Herramientas actuales · opcional','Current tools · optional')}</span><input id="brief-tools" data-brief-input="tools" maxlength="200" value="${esc(briefInputs.tools)}"></label><label class="control-field" for="brief-volume"><span>${t('Casos al mes · opcional','Cases per month · optional')}</span><input id="brief-volume" data-brief-input="volume" type="number" min="0" max="100000" step="1" value="${esc(briefInputs.volume)}"></label><label class="control-field" for="brief-minutes"><span>${t('Minutos por caso · opcional','Minutes per case · optional')}</span><input id="brief-minutes" data-brief-input="minutes" type="number" min="0" max="480" step=".1" value="${esc(briefInputs.minutes)}"></label><p class="quiet wide">${t('El volumen declarado sirve para dimensionar trabajo; no representa ahorro. No incluyas información confidencial o datos personales innecesarios.','Declared volume helps size the work; it does not represent savings. Do not include confidential information or unnecessary personal data.')}</p><button class="button wide" type="submit">${t('Preparar ficha local','Prepare local brief')}</button></form><aside class="brief-preview"><h3>${t('Una ficha para revisar','A brief to review')}</h3><p class="quiet" id="brief-status" role="status">${t('Completa los tres campos del recorrido. Nada se envía al preparar esta ficha.','Complete the three workflow fields. Preparing this brief submits nothing.')}</p><div id="brief-prepared" hidden><textarea class="brief-output" id="brief-output-text" readonly aria-label="${t('Ficha preparada','Prepared brief')}"></textarea><div class="brief-actions"><button class="button button-outline" data-brief-copy type="button">${t('Copiar ficha','Copy brief')}</button><button class="button button-outline" data-brief-download type="button">${t('Descargar TXT','Download TXT')}</button></div><p class="quiet">${t('La ficha no se comparte automáticamente. El sitio principal permite iniciar una conversación cuando decidas hacerlo.','The brief is not shared automatically. The main website lets you start a conversation when you decide to do so.')}</p><a class="text-link" href="${contactPath()}">${t('Ir a compartir mi caso','Go to share my case')}</a></div></aside></div></section>`;}

