const LAB_FUNCTIONS={packet:inspectPacket,order:reviseOrder,stock:reserveUnits,equipment:inspectEquipment,receipt:reconcileReceipt,opportunity:qualifyOpportunity};
const LAB_FIELD_NAMES={expectedPeriod:['Periodo esperado','Expected period'],documentPeriod:['Periodo recibido','Received period'],hasAttachment:['Documento presente','Document present'],approved:['Aprobación expresa','Explicit approval'],stock:['Existencias','Stock'],committed:['Unidades comprometidas','Committed units'],requested:['Unidades solicitadas','Requested units'],existingReservation:['Esta reserva ya está incluida','This reservation is already included'],tagged:['Equipo identificado','Equipment identified'],authorized:['Trabajo autorizado','Work authorized'],attachment:['Soporte de servicio','Service attachment'],expected:['Importe esperado · COP','Expected amount · COP'],received:['Importe reportado · COP','Reported amount · COP'],referenceMatches:['La referencia coincide','Reference matches'],reviewed:['Revisión humana','Human review'],sourceVerified:['Fuente verificada','Source verified'],mailboxVerified:['Buzón verificado','Mailbox verified'],priorContact:['Contacto previo','Prior contact'],suppressed:['No contactar','Do not contact'],humanApproved:['Aprobación humana','Human approval'],acknowledged:['Acuse automático','Automatic acknowledgment'],meetingConfirmed:['Reunión confirmada','Meeting confirmed']};
function labIndex(){return`<main id="content" class="container"><section class="case-head"><p class="eyebrow">${t('LABORATORIO DE CONTROLES','CONTROL LAB')}</p><h1>${t('Seis decisiones.<br><em>Reglas visibles.</em>','Six decisions.<br><em>Visible rules.</em>')}</h1><p class="lead">${t('Los modelos originales siguen funcionando de manera independiente. Cambia una entrada y observa qué permite avanzar; son controles ficticios, sin conexión operativa.','The original models still work independently. Change an input and inspect what allows progress; these are fictional controls with no operational connection.')}</p></section><section class="section"><div class="lab-grid">${LABS.map((lab,i)=>`<article class="lab-card"><span class="eyebrow">0${i+1} / ${t('CONTROL FICTICIO','FICTIONAL CONTROL')}</span><h2>${esc(text(lab.name))}</h2>${a(lab[language],t('Probar el control','Try the control'))}</article>`).join('')}</div></section></main>`;}
function labControls(id,s){if(id==='order')return`<label class="control-field"><span>${t('Cantidad aprobada','Approved units')}</span><input type="number" min="1" data-lab-field="baseline.units" value="${s.baseline.units}"></label><label class="control-field"><span>${t('Cantidad solicitada','Requested units')}</span><input type="number" min="1" data-lab-field="requested.units" value="${s.requested.units}"></label><label class="control-field"><span>${t('Acabado aprobado','Approved finish')}</span><input maxlength="80" data-lab-field="baseline.finish" value="${esc(s.baseline.finish)}"></label><label class="control-field"><span>${t('Acabado solicitado','Requested finish')}</span><input maxlength="80" data-lab-field="requested.finish" value="${esc(s.requested.finish)}"></label><label class="control-field check"><input type="checkbox" data-lab-field="approved" ${s.approved?'checked':''}><span>${t('Autorizar esta versión','Approve this version')}</span></label>`;return Object.entries(s).map(([key,value])=>{const label=LAB_FIELD_NAMES[key]?t(...LAB_FIELD_NAMES[key]):key;return typeof value==='boolean'?`<label class="control-field check"><input type="checkbox" data-lab-field="${key}" ${value?'checked':''}><span>${label}</span></label>`:`<label class="control-field"><span>${label}</span><input data-lab-field="${key}" type="${typeof value==='number'?'number':'text'}" value="${esc(value)}" ${typeof value==='number'?'min="0"':'maxlength="20"'}></label>`;}).join('');}
function labFacts(id,s,r){if(id==='packet')return{expectedPeriod:s.expectedPeriod,documentPeriod:s.documentPeriod,approved:s.approved};if(id==='order')return{units:s.requested.units,approved:r.productionAllowed,changeCount:r.changes.length};if(id==='stock')return{available:r.availableAfter,reservedNow:r.reservedNow,existingReservation:s.existingReservation};if(id==='equipment')return{tagged:s.tagged,authorized:s.authorized,attachment:s.attachment};if(id==='receipt')return{expectedAmount:s.expected,reportedAmount:s.received,difference:r.difference,recognizedIncome:r.recognizedIncome};return{humanApproved:r.allowed,acknowledged:s.acknowledged,sampleMeeting:s.meetingConfirmed,sales:0};}
function labIssues(r){return r.issues||r.missing||r.reasons||(r.reason&&!['reserved','already_reserved'].includes(r.reason)?[r.reason]:[]);}
function labPage(lab){if(!labStates.has(lab.id))labStates.set(lab.id,structuredClone(LAB_INITIAL[lab.id]));const s=labStates.get(lab.id),r=labResults.get(lab.id)||LAB_FUNCTIONS[lab.id](s),ready=r.ok===true||r.allowed===true||r.productionAllowed===true;return`<main id="content"><div class="container"><section class="case-head"><div class="breadcrumb">${a(labHome(language),t('Laboratorio','Control lab'))}<span>/</span><span>${esc(text(lab.name))}</span></div><p class="eyebrow">${t('MODELO FUNCIONAL INDEPENDIENTE','INDEPENDENT FUNCTIONAL MODEL')}</p><h1>${esc(text(lab.name))}</h1><p class="lead">${t('Cambia las condiciones y evalúa el resultado. Este control conserva el contrato original del modelo y utiliza únicamente los datos ficticios de esta sesión.','Change the conditions and evaluate the result. This control preserves the original model contract and uses only this session’s fictional data.')}</p></section></div><section class="simulation-section"><div class="container"><div class="simulation-heading"><h2>${t('Probar una condición.','Try a condition.')}</h2><button class="text-link" data-lab-reset>${t('Restablecer','Reset')}</button></div><div class="workspace"><aside class="controls-panel"><p class="controls-label">${t('CONDICIONES DE LA MUESTRA','SAMPLE CONDITIONS')}</p>${labControls(lab.id,s)}<div class="action-stack"><button class="button button-wine" data-lab-evaluate type="button">${t('Evaluar control','Evaluate control')}</button></div></aside><div class="result-panel"><div class="result-top"><div><span class="system-label">${t('RESULTADO DEL MODELO','MODEL RESULT')}</span><h3>${ready?t('Condiciones completas','Conditions complete'):t('Revisión pendiente','Review pending')}</h3></div><span class="state-label">${t('DATOS FICTICIOS','FICTIONAL DATA')}</span></div>${factsGrid(labFacts(lab.id,s,r))}${labIssues(r).length?`<ul class="check-list">${labIssues(r).map((x,i)=>`<li><span>${String(i+1).padStart(2,"0")}</span><span>${esc(issue(x))}</span></li>`).join("")}</ul>`:""}<p class="result-explanation">${lab.id==='stock'?t('Una reserva registrada se añade a las unidades comprometidas de esta sesión. Repetirla conserva el saldo y reserva cero unidades nuevas.','A recorded reservation is added to this session’s committed units. Repeating it retains the balance and reserves zero new units.'):lab.id==='receipt'?t('Un importe consistente puede quedar revisado, pero este modelo no reconoce ingresos ni acredita un pago real.','A consistent amount can be reviewed, but this model recognizes no income and establishes no real payment.'):lab.id==='opportunity'?t('Un acuse o una reunión no son una venta. Fuente, canal, historial y aprobación son condiciones separadas.','An acknowledgment or meeting is not a sale. Source, channel, history and approval are separate conditions.'):t('Las condiciones del ejemplo preparan una decisión; la aprobación humana y el contexto siguen visibles.','The example conditions prepare a decision; human approval and context remain visible.')}</p>${lab.id==='order'?`<ul class="check-list">${r.changes.map((x,i)=>`<li><span>0${i+1}</span><span>${x.field==='units'?t('Unidades','Units'):t('Acabado','Finish')}: ${esc(x.before)} → ${esc(x.after)}</span></li>`).join('')}</ul>`:''}</div></div><p class="legacy-note">${t('Una simulación no reserva existencias, confirma dinero o contacta personas fuera de este navegador.','A simulation reserves no stock, confirms no funds and contacts no person outside this browser.')}</p></div></section><div class="container section">${a(homePath(language),t('Volver a los desarrollos completos','Back to the complete developments'),'button button-outline','desarrollos')}</div>${contact()}</main>`;}
function notFound(){return`<main id="content" class="container not-found"><p class="eyebrow">${t('RUTA NO DISPONIBLE','ROUTE UNAVAILABLE')}</p><h1>${t('Volvamos al recorrido.','Back to the workflow.')}</h1><p>${t('Este enlace no corresponde a un caso de la demostración. Puedes abrir el catálogo o recuperar los seis controles originales.','This link does not match a demonstration case. Open the catalogue or return to the six original controls.')}</p>${a(homePath(language),t('Ver desarrollos','View developments'),'button')}</main>`;}
function render(){document.documentElement.lang=language;document.title=route.view==='case'?text(CASES.find(x=>x.id===route.caseId).title)+' · Automatizaciones Torres':t('Desarrollos destacados','Featured developments')+' · Automatizaciones Torres';let body=route.view==='home'?home():route.view==='case'?casePage(CASES.find(x=>x.id===route.caseId)):route.view==='labIndex'?labIndex():route.view==='lab'?labPage(LABS.find(x=>x.id===route.legacyId)):notFound();body=body.replace('<main id="content"','<main id="content" tabindex="-1"');app.innerHTML=header()+body+footer();privacy.setLocale(language);requestAnimationFrame(measureAnalyticsSections);}
function navigate(href,{replace=false}={}){const url=new URL(href,location.origin);if(url.origin!==location.origin)return false;history[replace?'replaceState':'pushState']({},'',url.pathname+url.search+url.hash);route=resolveRoute(url.pathname,url.search,CASES);language=route.language;render();trackRouteNavigation();requestAnimationFrame(()=>{if(url.hash)document.getElementById(url.hash.slice(1))?.scrollIntoView();else window.scrollTo({top:0,behavior:'instant'});});return true;}
function refreshSimulation(){const c=CASES.find(x=>x.id===route.caseId),root=document.getElementById('simulation-root');if(root&&c)root.innerHTML=simulation(c);}
function download(text,filename){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();URL.revokeObjectURL(url);}
function invalidateBrief(){preparedBrief=null;const target=document.getElementById('brief-prepared');if(target)target.hidden=true;const status=document.getElementById('brief-status');if(status)status.textContent=t('La ficha cambió. Prepárala de nuevo para revisar esta versión.','The brief changed. Prepare it again to review this version.');}
app.addEventListener('click',async event=>{
 const element=event.target.closest('a,button');if(!element)return;
 if(element.id==='menu-toggle'){const nav=document.getElementById('site-nav'),open=element.getAttribute('aria-expanded')!=='true';element.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);return;}
 if(element.id==='language-switch'){language=language==='es'?'en':'es';preparedBrief=null;const next=translatedRoute(route,language,CASES);navigate(next);track('language_change',{ui_language:language});return;}
 if(element.dataset.filter){filter=element.dataset.filter;document.getElementById('development-grid').innerHTML=selectedCases().map(card).join('');document.querySelector('.filters').innerHTML=filters();document.querySelector('[data-filter="'+filter+'"]')?.focus();return;}
 if(element.dataset.briefCase){event.preventDefault();briefCase=element.dataset.briefCase;preparedBrief=null;navigate(homePath(language));requestAnimationFrame(()=>document.getElementById('brief-builder')?.scrollIntoView());return;}
 if(element.dataset.scroll){event.preventDefault();const id=element.dataset.scroll;if(document.getElementById(id))document.getElementById(id).scrollIntoView();else{navigate(homePath(language));requestAnimationFrame(()=>document.getElementById(id)?.scrollIntoView());}return;}
 if(element.matches('[data-nav]')){if(event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;event.preventDefault();navigate(element.getAttribute('href'));return;}
 if(element.dataset.contact)track('contact_intent',{channel:element.dataset.contact,placement:'collaborate',ui_language:language});
 if(element.hasAttribute('data-reset')&&route.view==='case'){states.set(route.caseId,createScenario(route.caseId));refreshSimulation();return;}
 if(element.dataset.action&&route.view==='case'){const updated=transitionScenario(states.get(route.caseId),{type:element.dataset.action,choice:element.dataset.choice});states.set(route.caseId,updated);refreshSimulation();track('demo_evaluate',{example_id:route.caseId,result_category:analyticsResultCategory(evaluateScenario(updated).category),ui_language:language});requestAnimationFrame(measureAnalyticsSections);return;}
 if(element.hasAttribute('data-snapshot')&&route.view==='case'){const c=CASES.find(x=>x.id===route.caseId),s=states.get(route.caseId);download([`Automatizaciones Torres · ${text(c.title)}`,t('MUESTRA FICTICIA · NO ES UN REGISTRO OPERATIVO','FICTIONAL SAMPLE · NOT AN OPERATIONAL RECORD'),JSON.stringify({fictional:true,input:s,result:evaluateScenario(s)},null,2)].join('\n\n'),c.id+'-sample.txt');return;}
 if(element.hasAttribute('data-brief-copy')&&preparedBrief){const status=document.getElementById('brief-status');try{await navigator.clipboard.writeText(preparedBrief.text);status.textContent=t('Ficha copiada. Tú decides cómo compartirla.','Brief copied. You decide how to share it.');}catch{document.getElementById('brief-output-text').select();status.textContent=t('Selecciona y copia el texto de la ficha.','Select and copy the brief text.');}return;}
 if(element.hasAttribute('data-brief-download')&&preparedBrief){download(preparedBrief.text,'automatizaciones-torres-workflow.txt');track('brief_download',{example_id:briefCase,relationship_type:'business',ui_language:language});return;}
 if(element.hasAttribute('data-lab-reset')){labStates.set(route.legacyId,structuredClone(LAB_INITIAL[route.legacyId]));labResults.delete(route.legacyId);render();return;}
 if(element.hasAttribute('data-lab-evaluate')){const id=route.legacyId,s=labStates.get(id),r=LAB_FUNCTIONS[id](s);labResults.set(id,r);if(id==='stock'&&r.ok&&r.reservedNow>0){s.committed+=r.reservedNow;s.existingReservation=true;}render();track('demo_evaluate',{example_id:id,result_category:r.stage==='invalid'?'invalid':r.reason==='already_reserved'?'unchanged':r.ok||r.allowed||r.productionAllowed?'ready':'needs_review',ui_language:language});}
});
app.addEventListener('change',event=>{const el=event.target;if(el.dataset.field&&route.view==='case'){const id=el.id,value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;states.set(route.caseId,transitionScenario(states.get(route.caseId),{type:'set',field:el.dataset.field,value}));refreshSimulation();document.getElementById(id)?.focus();}
 if(el.dataset.labField&&route.view==='lab'){const s=labStates.get(route.legacyId),value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value,parts=el.dataset.labField.split('.');if(parts.length===2)s[parts[0]][parts[1]]=value;else s[parts[0]]=value;labResults.delete(route.legacyId);render();}
});
app.addEventListener('input',event=>{const key=event.target.dataset.briefInput;if(key){briefInputs[key]=event.target.value;invalidateBrief();}});
app.addEventListener('submit',event=>{if(event.target.id!=='brief-form')return;event.preventDefault();const c=CASES.find(x=>x.id===briefCase),r=prepareLocalBrief(briefInputs,{title:text(c.title),language,path:c.routes[language]}),status=document.getElementById('brief-status');if(!r.ok){status.textContent=t('Revisa los campos: ','Check these fields: ')+r.errors.map(x=>({entry:t('entrada','input'),decision:t('decisión','decision'),output:t('salida','output'),volume:t('volumen','volume'),minutes:t('minutos','minutes')})[x]).join(', ');document.getElementById('brief-'+r.errors[0])?.focus();return;}preparedBrief=r;document.getElementById('brief-prepared').hidden=false;document.getElementById('brief-output-text').value=r.text;status.textContent=t('Ficha preparada localmente. Revisa su contenido antes de compartir.','Brief prepared locally. Review its contents before sharing.');track('brief_prepared',{example_id:briefCase,relationship_type:'business',ui_language:language});});
app.addEventListener('keydown',event=>{if(event.key==='Escape'){const nav=document.getElementById('site-nav'),button=document.getElementById('menu-toggle');if(nav?.classList.contains('open')){nav.classList.remove('open');button.setAttribute('aria-expanded','false');button.focus();}}});
window.addEventListener('popstate',()=>{route=resolveRoute(location.pathname,location.search,CASES);language=route.language;render();trackRouteNavigation();});
window.addEventListener('scroll',measureAnalyticsSections,{passive:true});
render();trackRouteNavigation(true);if(location.hash)requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView());
